#!/usr/bin/env python3
"""Narrow distribution exception: exact generated bytes, never arbitrary media."""
import hashlib
import importlib.util
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
spec = importlib.util.spec_from_file_location("starter", ROOT / "Tools/generate-starter-kar.py")
starter = importlib.util.module_from_spec(spec)
spec.loader.exec_module(starter)


def verify(root=ROOT / "Resources/StarterKaraoke"):
    expected = {title.lower().replace(" ", "-") + ".kar": starter.render(title, bpm, lines)
                for title, bpm, lines in starter.SONGS}
    expected["kanta-tone.sf2"] = starter.soundfont()
    manifest = json.loads((root / "manifest.json").read_text())
    assert len(manifest) == len(expected), "Unexpected manifest entries"
    assert {item["file"] for item in manifest} == set(expected), "Manifest file mismatch"
    for name, data in expected.items():
        assert (root / name).read_bytes() == data, f"Generated asset drift: {name}"
        digest = hashlib.sha256(data).hexdigest()
        assert next(item["sha256"] for item in manifest if item["file"] == name) == digest, name
    assert {p.name for p in root.iterdir()} <= set(expected) | {"manifest.json", "README.md"}, "Unexpected pack payload"
    print("Starter resource guard passed: three deterministic KAR songs and original procedural tone.")


if __name__ == "__main__":
    verify()
